def four_sum(nums, target):
    a = sorted(nums)
    n, out = len(a), []
    for i in range(n - 3):
        if i > 0 and a[i] == a[i - 1]:
            continue
        for j in range(i + 1, n - 2):
            if j > i + 1 and a[j] == a[j - 1]:
                continue
            need = target - a[i] - a[j]
            lo, hi = j + 1, n - 1
            while lo < hi:
                s = a[lo] + a[hi]
                if s < need:
                    lo += 1
                elif s > need:
                    hi -= 1
                else:
                    out.append([a[i], a[j], a[lo], a[hi]])
                    lo, hi = lo + 1, hi - 1
                    while lo < hi and a[lo] == a[lo - 1]:
                        lo += 1
    return out

