static List<int[]> fourSum(int[] nums, long target) {
    int[] a = nums.clone();
    Arrays.sort(a);
    int n = a.length;
    List<int[]> out = new ArrayList<>();
    for (int i = 0; i < n - 3; i++) {
        if (i > 0 && a[i] == a[i - 1]) continue;
        for (int j = i + 1; j < n - 2; j++) {
            if (j > i + 1 && a[j] == a[j - 1]) continue;
            long need = target - a[i] - a[j];
            int lo = j + 1, hi = n - 1;
            while (lo < hi) {
                long s = (long) a[lo] + a[hi];
                if (s < need) lo++;
                else if (s > need) hi--;
                else {
                    out.add(new int[] {a[i], a[j], a[lo], a[hi]});
                    lo++;
                    hi--;
                    while (lo < hi && a[lo] == a[lo - 1]) lo++;
                }
            }
        }
    }
    return out;
}

