static int cmpInt(const void* x, const void* y) {
    int a = *(const int*)x, b = *(const int*)y;
    return (a > b) - (a < b);
}

int fourSum(const int* nums, int n, long long target, int (*out)[4]) {
    int* a = malloc((n > 0 ? n : 1) * sizeof(int));
    memcpy(a, nums, n * sizeof(int));
    qsort(a, n, sizeof(int), cmpInt);
    int found = 0;
    for (int i = 0; i < n - 3; i++) {
        if (i > 0 && a[i] == a[i - 1]) continue;
        for (int j = i + 1; j < n - 2; j++) {
            if (j > i + 1 && a[j] == a[j - 1]) continue;
            long long need = target - a[i] - a[j];
            int lo = j + 1, hi = n - 1;
            while (lo < hi) {
                long long s = (long long)a[lo] + a[hi];
                if (s < need) lo++;
                else if (s > need) hi--;
                else {
                    int* q = out[found++];
                    q[0] = a[i]; q[1] = a[j]; q[2] = a[lo]; q[3] = a[hi];
                    lo++;
                    hi--;
                    while (lo < hi && a[lo] == a[lo - 1]) lo++;
                }
            }
        }
    }
    free(a);
    return found;
}

