def count_triangles(sides):
    a = sorted(sides)
    count = 0
    for k in range(len(a) - 1, 1, -1):
        lo, hi = 0, k - 1
        while lo < hi:
            if a[lo] + a[hi] > a[k]:
                count += hi - lo
                hi -= 1
            else:
                lo += 1
    return count

