static long countTriangles(int[] sides) {
    int[] a = sides.clone();
    Arrays.sort(a);
    long count = 0;
    for (int k = a.length - 1; k >= 2; k--) {
        int lo = 0, hi = k - 1;
        while (lo < hi) {
            if (a[lo] + a[hi] > a[k]) {
                count += hi - lo;
                hi--;
            } else {
                lo++;
            }
        }
    }
    return count;
}

